1	export type Cell = [x: number, y: number];
2	
3	const NEIGHBOR_OFFSETS: ReadonlyArray<Cell> = [
4	  [-1, -1], [-1, 0], [-1, 1],
5	  [ 0, -1],          [ 0, 1],
6	  [ 1, -1], [ 1, 0], [ 1, 1],
7	];
8	
9	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
10	
11	const survives = (isAlive: boolean, neighbors: number): boolean =>
12	  neighbors === 3 || (isAlive && neighbors === 2);
13	
14	const neighborsOf = ([x, y]: Cell): Cell[] =>
15	  NEIGHBOR_OFFSETS.map(([dx, dy]) => [x + dx, y + dy]);
16	
17	const countNeighborInfluences = (cells: Cell[]): Map<string, { cell: Cell; count: number }> => {
18	  const counts = new Map<string, { cell: Cell; count: number }>();
19	  for (const cell of cells) {
20	    for (const neighbor of neighborsOf(cell)) {
21	      const key = cellKey(neighbor);
22	      const entry = counts.get(key);
23	      if (entry) entry.count++;
24	      else counts.set(key, { cell: neighbor, count: 1 });
25	    }
26	  }
27	  return counts;
28	};
29	
30	export function nextGeneration(cells: Cell[]): Cell[] {
31	  const alive = new Set(cells.map(cellKey));
32	  const influences = countNeighborInfluences(cells);
33	
34	  const result: Cell[] = [];
35	  for (const [key, { cell, count }] of influences) {
36	    if (survives(alive.has(key), count)) result.push(cell);
37	  }
38	  return result;
39	}
