const countNeighborInfluences = (cells: Cell[]): Map<string, { cell: Cell; count: number }> => {
  const counts = new Map<string, { cell: Cell; count: number }>();
  for (const cell of cells) {
    for (const neighbor of neighborsOf(cell)) {
      const key = cellKey(neighbor);
      const entry = counts.get(key);
      if (entry) entry.count++;
      else counts.set(key, { cell: neighbor, count: 1 });
    }
  }
  return counts;
};

export function nextGeneration(cells: Cell[]): Cell[] {
  const alive = new Set(cells.map(cellKey));
  const influences = countNeighborInfluences(cells);

  const result: Cell[] = [];
  for (const [key, { cell, count }] of influences) {
    if (survives(alive.has(key), count)) result.push(cell);
  }
  return result;
}

